      fl_value fl_t7447 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t7445, gotovye, &fl_t7447, error));
      arnosti = hvost;
      zanyatye = fl_t7444;
      gotovye = fl_t7447;
      continue;
