static fl_status kompilyator_flang_odinakovye_spiski_tipov_body(fl_ctx *ctx, fl_value pervye, fl_value vtorye, fl_value *result, fl_error *error) {
  for (;;) {
    FL_TRY(fl_tick(ctx, "Одинаковые списки типов", error));
    if (fl_chain_empty(pervye)) {
      fl_value fl_t10937 = fl_nothing(); /* «пусто» */
      FL_TRY(fl_b_pusto(ctx, vtorye, &fl_t10937, error));
      *result = fl_t10937;
      return FL_OK;
    } else if (fl_chain_cons(pervye)) {
      const fl_value pervyy = fl_chain_head(pervye); /* голова «первый» */
      const fl_value prochie = fl_chain_tail(pervye); /* хвост «прочие» */
      fl_value fl_t10938 = fl_nothing(); /* «пусто» */
      FL_TRY(fl_b_pusto(ctx, vtorye, &fl_t10938, error));
      bool fl_t10939 = false;
      FL_TRY(fl_cond(ctx, fl_t10938, &fl_t10939, error));
      if (fl_t10939) {
        *result = fl_flag(false);
        return FL_OK;
      } else {
        fl_value fl_t10940 = fl_nothing(); /* «голова» */
        FL_TRY(fl_b_golova(ctx, vtorye, &fl_t10940, error));
        fl_value fl_t10941 = fl_nothing();
        FL_TRY(kompilyator_flang_odinakovye_tipy(ctx, pervyy, fl_t10940, &fl_t10941, error));
        bool fl_t10942 = false;
        FL_TRY(fl_cond(ctx, fl_t10941, &fl_t10942, error));
        if (fl_t10942) {
          fl_value fl_t10943 = fl_nothing(); /* «хвост» */
          FL_TRY(fl_b_hvost(ctx, vtorye, &fl_t10943, error));
          pervye = prochie;
          vtorye = fl_t10943;
          continue;
        } else {
          *result = fl_flag(false);
          return FL_OK;
        }
      }
    } else {
      return fl_match_fail(ctx, pervye, error);
    }
  }
}

